                    is_valid=False,
                    status="EXPIRED",
                    reasons=tuple(reasons),
                    cert=cert,
                )
        except ValueError as exc:
            reasons.append(f"Invalid date format in certificate: {exc}")
            return VerificationResult(
                is_valid=False,
                status="INVALID_FORMAT",
                reasons=tuple(reasons),
                cert=cert,
            )

