"""Unit tests for certificate text validation and Markdown escaping."""

import unittest

from aegean_licensing.sanitize import escape_markdown, normalize_text


class TestNormalizeText(unittest.TestCase):
    """Test trimming, length limits, and control-character rejection."""

    def test_trims_surrounding_whitespace(self):
        self.assertEqual(normalize_text("licensee_name", "  Acme Corp  "), "Acme Corp")

    def test_rejects_non_strings(self):
        with self.assertRaises(ValueError):
            normalize_text("licensee_name", 42)  # type: ignore[arg-type]

    def test_rejects_overlong_values(self):
        with self.assertRaises(ValueError):
            normalize_text("licensee_name", "x" * 201)

    def test_rejects_control_characters(self):
        for value in ("Acme\x00Corp", "Acme\x1b[31m", "Acme\u202eevil", "Acme\u2028Corp"):
            with self.assertRaises(ValueError, msg=repr(value)):
                normalize_text("licensee_name", value)

    def test_single_line_fields_reject_newlines(self):
        with self.assertRaises(ValueError):
            normalize_text("licensee_name", "Acme\nCorp")

    def test_notes_may_contain_newlines(self):
        self.assertEqual(
            normalize_text("notes", "line one\nline two", max_length=2000, allow_newlines=True),
            "line one\nline two",
        )

    def test_notes_still_reject_other_controls(self):
        with self.assertRaises(ValueError):
            normalize_text("notes", "line\x00", allow_newlines=True)


class TestEscapeMarkdown(unittest.TestCase):
    """Test that Markdown control characters render literally."""

    def test_escapes_markdown_syntax(self):
        escaped = escape_markdown("**bold** [link](x) `code` # header")
        self.assertNotIn("**bold**", escaped)
        self.assertNotIn("[link](x)", escaped)
        self.assertIn(r"\*\*bold\*\*", escaped)
        self.assertIn(r"\`code\`", escaped)

    def test_flattens_newlines(self):
        self.assertEqual(escape_markdown("a\nb\r\nc"), "a b c")

    def test_leaves_plain_text_readable(self):
        self.assertEqual(escape_markdown("Acme Corp"), "Acme Corp")


if __name__ == "__main__":
    unittest.main()

