name: Contributor License Agreement (CLA) Check

on:
  pull_request_target:
    types: [opened, synchronize, reopened, labeled]
  issue_comment:
    types: [created]

permissions:
  contents: write
  pull-requests: write
  issues: write

concurrency:
  group: cla-${{ github.repository }}-${{ github.event.pull_request.number || github.event.issue.number }}
  cancel-in-progress: false

jobs:
  cla-verification:
    runs-on: ubuntu-latest
    steps:
      - name: Check Contributor License Agreement
        uses: actions/github-script@v7
        with:
          script: |
            const REGISTER_PATH = '.github/cla-signatures.json';
            const REGISTER_MESSAGE = 'chore(cla): record contributor license acceptance';

            const isPR = !!context.payload.pull_request;
            const pr = isPR ? context.payload.pull_request : null;
            if (!isPR && !context.payload.issue?.pull_request) return;

            const prNumber = isPR ? pr.number : context.payload.issue.number;
            const author = isPR ? pr.user.login : context.payload.issue.user.login;
            const repoOwner = context.repo.owner;

            // Maintainers and bots do not need a CLA check
            if (author === repoOwner || author.endsWith('[bot]')) {
              console.log(`Author ${author} is repository owner or bot; CLA check passed.`);
              return;
            }

            async function loadRegister() {
              try {
                const response = await github.rest.repos.getContent({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  path: REGISTER_PATH,
                });
                const text = Buffer.from(response.data.content, 'base64').toString('utf8').trim();
                const parsed = text ? JSON.parse(text) : {};
                return {
                  signatures: Array.isArray(parsed.signatures) ? parsed.signatures : [],
                  revoked: Array.isArray(parsed.revoked) ? parsed.revoked : [],
                  sha: response.data.sha,
                };
              } catch (error) {
                if (error.status === 404) return { signatures: [], revoked: [], sha: null };
                throw error;
              }
            }

            function findEntry(entries, login) {
              const needle = login.toLowerCase();
              return entries.find(entry => String(entry.login || '').toLowerCase() === needle);
            }

            let register = await loadRegister();

