def _print_text(content: str) -> None:
    """Print template text, falling back to UTF-8 bytes on a console that cannot encode it."""
    stream = sys.stdout
    encoding = getattr(stream, "encoding", None) or "utf-8"
    try:
        content.encode(encoding)
    except (UnicodeEncodeError, LookupError):
        buffer = getattr(stream, "buffer", None)
        if buffer is not None:
            buffer.write(content.encode("utf-8", errors="replace") + b"\n")
            buffer.flush()
            return
        content = content.encode(encoding, errors="replace").decode(encoding, errors="replace")
    print(content)


def _handle_template(args: argparse.Namespace) -> int:
    out_dir = Path(args.output_dir) if args.output_dir else None

    templates_map = {
        "rider": ("DUAL_LICENSE_NOTICE.txt", get_dual_license_rider()),
        "commercial": ("COMMERCIAL.md", get_commercial_md()),
        "pyproject": ("pyproject_snippet.toml", get_pyproject_snippet()),
        "al": ("AL-1.0.md", get_personal_use_license()),
        "commercial-order": ("COMMERCIAL-LICENSE-TEMPLATE-DRAFT.md", get_commercial_agreement_template()),
        "cla": ("CONTRIBUTING_CLA.md", get_contributor_cla()),
        "asset-policy": ("ASSET_POLICY.md", get_asset_policy()),
        "backward-compat": ("BACKWARD-COMPATIBILITY-DRAFT.md", get_backward_compatibility_policy()),
        "migration": ("PORTFOLIO-MIGRATION-PLAN.md", get_portfolio_migration_plan()),
        "privacy": ("PRIVACY.md", get_privacy_notice()),
        "cla-action": ("cla-check.yml", get_cla_workflow()),
    }

    if args.kind in templates_map:
        filename, content = templates_map[args.kind]
        if out_dir:
            out_dir.mkdir(parents=True, exist_ok=True)
            target_path = out_dir / filename
            with open(target_path, "w", encoding="utf-8") as f:
                f.write(content)
            print(f"Wrote {target_path}")
        else:
            _print_text(content)
    elif args.kind == "all":
        if out_dir:
            out_dir.mkdir(parents=True, exist_ok=True)
            for fname, content in templates_map.values():
                target_path = out_dir / fname
                with open(target_path, "w", encoding="utf-8") as f:
                    f.write(content)
                print(f"Wrote {target_path}")
        else:
            for fname, content in templates_map.values():
                print(f"=== {fname} ===")
                _print_text(content)

    return 0


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = _build_parser()
    args = parser.parse_args(argv)

    if args.command == "issue":
        return _handle_issue(args)
    elif args.command == "verify":
        return _handle_verify(args)
    elif args.command == "revoke":
        return _handle_revoke(args)
    elif args.command == "audit":
        return _handle_audit(args)
    elif args.command == "template":
        return _handle_template(args)
    return 0


if __name__ == "__main__":
    sys.exit(main())

