def _add_paths(parser: argparse.ArgumentParser, signing: bool = False) -> None:
    """The shared location options; each defaults to the AIKit workspace layout (ADR-003)."""
    parser.add_argument("--register", default=None, metavar="PATH",
                        help="Public register (default: ../aegean-licensing/licenses/issued.json).")
    parser.add_argument("--db", default=None, metavar="PATH", help="Database (default: data/ops.sqlite3).")
    parser.add_argument("--output-dir", default=None, metavar="PATH",
                        help="Where certificate files are written (default: data/certs).")
    parser.add_argument("--json", action="store_true", help="Answer with one JSON object on stdout.")
    if signing:
        signer_group = parser.add_mutually_exclusive_group()
        signer_group.add_argument("--key", default=None, help="Secret HMAC signing key (prefer --key-file).")
        signer_group.add_argument("--key-file", default=None, metavar="PATH",
                                  help="File holding the signing key (default: ~/.aegean/signing.key).")


def _settings(args: argparse.Namespace) -> operations.OpsSettings:
    return operations.default_settings(args.register, getattr(args, "key_file", None),
                                       args.output_dir, args.db)


def _signing_key(args: argparse.Namespace, settings: operations.OpsSettings) -> str:
    """--key, else --key-file, else the default key file; no key at all is an error."""
    if args.key:
        return args.key
    if not args.key_file and not settings.key_file.is_file():
        raise ValueError(f"a signing key is required: pass --key-file or --key, or keep it in {settings.key_file}.")
    return operations.read_signing_key(settings.key_file)


def _emit(args: argparse.Namespace, result: Any, lines: Sequence[str]) -> None:
    if args.json:
        print(json.dumps({"ok": True, "result": result}, indent=2, default=str))
    else:
        for line in lines:
            print(line)


def _fail(args: argparse.Namespace, message: str) -> int:
    if args.json:
        print(json.dumps({"ok": False, "error": message}))
    else:
        print(f"Error: {message}", file=sys.stderr)
    return 1


def _handle_issue(args: argparse.Namespace) -> int:
    settings = _settings(args)
    try:
        result = operations.issue(
            settings, _signing_key(args, settings), licensee_name=args.licensee,
            licensee_contact=args.contact, license_type=args.license_type,
            projects=[p.strip() for p in args.projects.split(",") if p.strip()], scope=args.scope,
            tier=args.tier, allowances=args.allow, expires_at=args.expires, notes=args.notes,
            licensee_address=args.address, licensee_registration=args.registration,
            licensee_country=args.country)
    except Exception as exc:  # hygiene: allow any issuance failure is reported, never a traceback
        return _fail(args, f"Failed to issue certificate: {exc}")
    cert = result["certificate"]
    _emit(args, result, [
        f"Certificate ID : {cert['cert_id']}",
        f"Licensee       : {cert['licensee_name']} <{cert['licensee_contact']}>",
        f"License        : {cert['license_type']}" + (f" ({cert['tier']})" if cert["tier"] else ""),
        f"Scope          : {cert['scope']}; allowances: {', '.join(cert['allowances']) or 'none'}",
        f"Expires        : {cert['expires_at'] or 'Perpetual'}",
        f"Serial         : {cert['serial']}",
        f"Saved to       : {result['file']}",
        f"Registered in  : {result['register']}",
        f"Stored in      : {result['database']}",
        "Commit and push the public register so verifiers see the certificate.",
    ])
    return 0


def _handle_verify(args: argparse.Namespace) -> int:
    """AUTHENTIC only when the certificate is listed, unrevoked, and signed with AegeanWorks' key."""
    settings = _settings(args)
    try:
        result = operations.verify(settings, _signing_key(args, settings), args.path,
                                   project=args.project, date=args.date)
    except ValueError as exc:
        return _fail(args, str(exc))
    _emit(args, result, [f"Status : {result['status']}", f"ID     : {result['cert_id']}",
                         f"Holder : {result['licensee']}", f"Serial : {result['serial']}",
                         *[f"  - {reason}" for reason in result["reasons"]]])
    return 0 if result["authentic"] else 1


def _handle_revoke(args: argparse.Namespace) -> int:
    try:
        result = operations.revoke(_settings(args), args.cert_id, args.reason)
    except (OSError, ValueError) as exc:
        return _fail(args, f"Failed to revoke certificate: {exc}")
    _emit(args, result, [f"Revoked {result['cert_id']} on {result['revoked_at']}: {result['reason']}",
                         "Commit and publish the register so verifiers see the revocation."])
    return 0


def _handle_records(args: argparse.Namespace) -> int:
    """list, edit, backup and erase: the database commands."""
    settings = _settings(args)
    try:
        with contextlib.closing(database.connect(settings.db_path)) as connection:
            if args.command == "list":
                records = database.list_records(connection, status=args.status, search=args.search)
                for record in records:
                    record.pop("certificate_json", None)
                _emit(args, {"certificates": records}, [
                    f"{r['cert_id']}  {r['status']:<7}  {r['issued_at']}  {r['licensee_name']}  "
                    f"<{r['current_contact']}>" for r in records] or ["No certificates."])
            elif args.command == "edit":
                fields = {k: v for k, v in (("current_contact", args.contact), ("internal_notes", args.notes))
                          if v is not None}
                if not fields:
                    raise ValueError("give --contact and/or --notes.")
                record = database.update_record(connection, args.cert_id, **fields)
                record.pop("certificate_json", None)
                _emit(args, {"certificate": record}, [f"Updated {args.cert_id}."])
            elif args.command == "backup":
                target = database.backup(connection, args.to)
                _emit(args, {"backup": str(target)}, [f"Backed up the database to {target}."])
            else:
                if not args.yes:
                    raise ValueError("erasing personal data cannot be undone; add --yes to confirm.")
                record = database.erase_personal_data(connection, args.cert_id)
                record.pop("certificate_json", None)
                _emit(args, {"certificate": record},
                      [f"Erased the personal data of {args.cert_id}; id, serial, dates and status remain."])
    except (OSError, ValueError) as exc:
        return _fail(args, str(exc))
    return 0


def _handle_ui(args: argparse.Namespace) -> int:
    settings = _settings(args)
    try:
        secret_key = REDACTED, settings)
    except ValueError as exc:
        return _fail(args, str(exc))
    webapp.serve(settings, secret_key, port=args.port, open_browser=not args.no_browser)
    return 0
